        col--; // 0-indexed

        // Find current heights
        auto getHeight = [&](int c) {
            for(int r = (int)board.size()-1; r >= 0; r--)
                if(board[r][c]) return r+1;
            return 0;
        };

        int landRow; // bottom row of block (0-indexed)
        if(ori == 'H'){
            int maxH = 0;
            for(int i = 0; i < len; i++) maxH = max(maxH, getHeight(col+i));
