            // Place block at row landRow, columns col to col+len-1
            while((int)board.size() <= landRow) board.push_back({0,0,0,0,0});
            for(int i = 0; i < len; i++) board[landRow][col+i] = 1;
        } else { // V
            int h = getHeight(col);
            landRow = h; // bottom of vertical block
            // Place len cells from landRow to landRow+len-1
            while((int)board.size() <= landRow+len-1) board.push_back({0,0,0,0,0});
            for(int i = 0; i < len; i++) board[landRow+i][col] = 1;
        }

        // Check for full rows and remove them
