#include <bits/stdc++.h>
using namespace std;

struct Block {
    char dir;
    int len;
    int pos;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Block> blocks;
    char dir;
    int len, pos;

    while (cin >> dir >> len >> pos) {
        blocks.push_back({dir, len, pos});
    }

    // Board width = 5, enough height.
    // Represent occupied cells row by row from bottom upward.
    // Each row is a 5-bit mask.
    vector<int> rows; // rows[0] = bottom row

    auto clear_full_rows = [&]() {
        vector<int> nxt;
        for (int mask : rows) {
            if (mask != 31) nxt.push_back(mask); // 31 = 11111b, full row
        }
        rows.swap(nxt);
    };

    for (auto &b : blocks) {
        if (b.dir == 'H') {
            // Horizontal block of length len starting at column pos (1-based)
            int mask = 0;
            for (int c = b.pos - 1; c < b.pos - 1 + b.len; ++c) {
                mask |= (1 << c);
            }

            int h = 0;
            while (h < (int)rows.size() && (rows[h] & mask) == 0) h++;

            if (h == (int)rows.size()) rows.push_back(0);
            rows[h] |= mask;

            clear_full_rows();
        } else {
            // Vertical block of length len in column pos (1-based)
            int col = b.pos - 1;
            int bit = 1 << col;

            int base = 0;
            while (base < (int)rows.size() && (rows[base] & bit) == 0) base++;

            for (int i = 0; i < b.len; ++i) {
                if (base + i == (int)rows.size()) rows.push_back(0);
                rows[base + i] |= bit;
            }

            clear_full_rows();
        }
    }

    long long ans = 0;
    for (int mask : rows) ans += __builtin_popcount(mask);

    cout << ans << '\n';
    return 0;
}

