#define WIDTH 5
#define MAX_HEIGHT 5000 // enough for up to 1000 blocks of length 5

int board[MAX_HEIGHT][WIDTH];
int top_row = 0; // current topmost row index used (0 = bottom)

// Drop a vertical block of given length at column col (0-indexed)
// Returns the row where the block comes to rest (bottom of block)
int drop_vertical(int col, int len) {
    // find the lowest row (highest index) where we can place the block
    int row = 0;
    for (int r = 0; r <= top_row; r++) {
        int blocked = 0;
        for (int i = 0; i < len; i++) {
            if (r + i <= top_row && board[r + i][col]) {
                blocked = 1;
                break;
            }
        }
        if (blocked) break;
        row = r;
    }
    // place block
    for (int i = 0; i < len; i++) {
        board[row + i][col] = 1;
    }
    // update top_row if needed
    if (row + len - 1 > top_row) top_row = row + len - 1;
    return row;
}

// Drop a horizontal block of given length at row (0 = bottom), starting at column col
void drop_horizontal(int row, int col, int len) {
    for (int i = 0; i < len; i++) {
        board[row][col + i] = 1;
    }
}

// Clear full rows and return number of rows cleared
int clear_rows() {
    int cleared = 0;
    int write_row = 0;
    for (int r = 0; r <= top_row; r++) {
        int full = 1;
        for (int c = 0; c < WIDTH; c++) {
            if (!board[r][c]) {
                full = 0;
                break;
            }
        }
        if (full) {
            cleared++;
        } else {
            if (write_row != r) {
                memcpy(board[write_row], board[r], WIDTH * sizeof(int));
            }
            write_row++;
        }
    }
    // zero out rows above new top
    for (int r = write_row; r <= top_row; r++) {
        memset(board[r], 0, WIDTH * sizeof(int));
    }
    top_row = write_row - 1;
    if (top_row < 0) top_row = 0;
    return cleared;
}

