static unsigned char board[MAXH][W];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int top = 0; // current used height

    for (int b = 0; b < n; b++) {
        char dir;
        int len, pos;
        scanf(" %c %d %d", &dir, &len, &pos);

        if (dir == 'H') {
            int c0 = pos - 1;
            int row = 0;

            // Find landing row: first row where any covered cell is occupied
            while (1) {
                int blocked = 0;
                for (int c = c0; c < c0 + len; c++) {
                    if (row < top && board[row][c]) {
                        blocked = 1;
                        break;
                    }
                }
                if (blocked) break;
                row++;
            }
            row--; // piece rests here

            if (row < 0) row = 0;
            if (row >= top) top = row + 1;

            for (int c = c0; c < c0 + len; c++) board[row][c] = 1;

            // Clear full rows, possibly repeatedly
            int r = row;
            while (r < top) {
                int full = 1;
                for (int c = 0; c < W; c++) {
                    if (!board[r][c]) {
                        full = 0;
                        break;
                    }
                }
                if (full) {
                    for (int i = r; i + 1 < top; i++) {
                        memcpy(board[i], board[i + 1], W);
                    }
                    memset(board[top - 1], 0, W);
                    top--;
                } else {
                    r++;
                }
            }
        } else { // Vertical
            int c = pos - 1;
            int base = 0;

            // Find landing base row: first occupied cell in this column
            while (base < top && !board[base][c]) base++;

            if (base + len > top) top = base + len;
            for (int r = base; r < base + len; r++) board[r][c] = 1;

            // Clear full rows in affected range, possibly repeatedly
            int r = base;
            if (r < 0) r = 0;
            while (r < top) {
                int full = 1;
                for (int cc = 0; cc < W; cc++) {
                    if (!board[r][cc]) {
                        full = 0;
                        break;
                    }
                }
                if (full) {
                    for (int i = r; i + 1 < top; i++) {
                        memcpy(board[i], board[i + 1], W);
                    }
                    memset(board[top - 1], 0, W);
                    top--;
                    if (r > 0) r--;
                } else {
                    r++;
                }
            }
        }
    }

    int ans = 0;
    for (int r = 0; r < top; r++) {
        for (int c = 0; c < W; c++) ans += board[r][c];
    }

    printf("%d\n", ans);
    return 0;
}

import java.util.Scanner;

public class TetrisSimulation {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] board = new int[2000][5]; // enough height
        int height = 0;

        for (int i = 0; i < n; i++) {
            int d = sc.nextInt();
            int len = sc.nextInt();

            if (d == 0) { // horizontal
                int col = sc.nextInt() - 1;
                int row = findDropRowHorizontal(board, height, col, len);
                placeHorizontal(board, row, col, len);
                height = Math.max(height, row + 1);
                // clear full rows and let things fall
                int cleared = clearFullRows(board, height);
                height -= cleared;
            } else { // vertical
                int col = sc.nextInt() - 1;
                int row = findDropRowVertical(board, height, col, len);
                placeVertical(board, row, col, len);
                height = Math.max(height, row + len);
                int cleared = clearFullRows(board, height);
                height -= cleared;
            }
        }

        int count = 0;
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < 5; c++) {
                if (board[r][c] == 1) count++;
            }
        }
        System.out.println(count);
    }

    static int findDropRowHorizontal(int[][] board, int height, int col, int len) {
        int row = 0;
        while (row < height) {
            boolean blocked = false;
            for (int c = col; c < col + len; c++) {
                if (board[row][c] == 1) {
                    blocked = true;
                    break;
                }
            }
            if (blocked) break;
            row++;
        }
        return row;
    }

    static void placeHorizontal(int[][] board, int row, int col, int len) {
        for (int c = col; c < col + len; c++) {
            board[row][c] = 1;
        }
    }

    static int findDropRowVertical(int[][] board, int height, int col, int len) {
        int row = 0;
        while (row < height) {
            if (board[row][col] == 1) break;
            row++;
        }
        // the block occupies rows row to row+len-1 if there is space
        return row;
    }

    static void placeVertical(int[][] board, int row, int col, int len) {
        for (int r = row; r < row + len; r++) {
            board[r][col] = 1;
        }
    }

    static int clearFullRows(int[][] board, int height) {
        int cleared = 0;
        int writeRow = 0;
        for (int r = 0; r < height; r++) {
            boolean full = true;
            for (int c = 0; c < 5; c++) {
                if (board[r][c] == 0) {
                    full = false;
                    break;
                }
            }
            if (full) {
                cleared++;
            } else {
                if (writeRow != r) {
                    for (int c = 0; c < 5; c++) {
                        board[writeRow][c] = board[r][c];
                    }
                }
                writeRow++;
            }
        }
        // clear the rows above new height
        for (int r = writeRow; r < height; r++) {
            for (int c = 0; c < 5; c++) {
                board[r][c] = 0;
            }
        }
        return cleared;
    }
}

import java.util.*;

public class Main {
    static List<boolean[]> board = new ArrayList<>();

    static int getHeight(int col) {
        for (int r = board.size() - 1; r >= 0; r--) {
            if (board.get(r)[col]) return r + 1;
        }
        return 0;
    }

    static void ensureRows(int maxRow) {
        while (board.size() <= maxRow) {
            board.add(new boolean[5]);
        }
    }

    static void clearFullRows() {
        for (int r = 0; r < board.size(); r++) {
            boolean full = true;
            for (int c = 0; c < 5; c++) {
                if (!board.get(r)[c]) { full = false; break; }
            }
            if (full) {
                board.remove(r);
                r--;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            String dir = sc.next();
            int len = sc.nextInt();
            int col = sc.nextInt() - 1; // 0-indexed

            if (dir.equals("H")) {
                // horizontal: cols col to col+len-1
                int maxH = 0;
                for (int c = col; c < col + len; c++) {
                    maxH = Math.max(maxH, getHeight(c));
                }
                ensureRows(maxH);
                for (int c = col; c < col + len; c++) {
                    board.get(maxH)[c] = true;
                }
            } else {
                // vertical: bottom at getHeight(col), length len upward
                int h = getHeight(col);
                ensureRows(h + len - 1);
                for (int i = 0; i < len; i++) {
                    board.get(h + i)[col] = true;
                }
            }

            clearFullRows();
        }

        int count = 0;
        for (boolean[] row : board) {
            for (boolean cell : row) {
                if (cell) count++;
            }
        }
        System.out.println(count);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        // board rows from bottom to top; each row is 5-bit mask
        ArrayList<Integer> board = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int d = fs.nextInt(); // 0: horizontal, 1: vertical
            int l = fs.nextInt(); // length
            int p = fs.nextInt(); // position (1-based, left column for horizontal, column for vertical)

            if (d == 0) {
                // horizontal block of length l placed across columns [p-1, p+l-2]
                int mask = ((1 << l) - 1) << (p - 1);

                int row = 0;
                while (true) {
                    if (row >= board.size()) {
                        board.add(mask);
                        break;
                    }
                    if ((board.get(row) & mask) != 0) {
                        if (row == 0) {
                            board.add(0, mask);
                        } else {
                            board.set(row - 1, board.get(row - 1) | mask);
                        }
                        break;
                    }
                    row++;
                }
            } else {
                // vertical block of length l in column p
                int bit = 1 << (p - 1);

                int row = 0;
                while (row < board.size() && (board.get(row) & bit) == 0) row++;

                // bottom of the vertical block will be at row
                for (int k = 0; k < l; k++) {
                    int r = row + k;
                    if (r >= board.size()) board.add(0);
                    board.set(r, board.get(r) | bit);
                }
            }

            // remove full rows and let above rows fall
            for (int r = 0; r < board.size(); ) {
                if (board.get(r) == 31) { // 11111
                    board.remove(r);
                } else {
                    r++;
                }
            }
        }

        long cells = 0;
        for (int mask : board) {
            cells += Integer.bitCount(mask);
        }

        System.out.println(cells);
    }
}

import sys

def main():
    input = sys.stdin.readline
    n = int(input().strip())

    # board[y][x], y=0 is the bottom row
    board = []

    def ensure_height(h):
        while len(board) < h:
            board.append([0] * 5)

    for _ in range(n):
        parts = input().split()
        d = parts[0]
        length = int(parts[1])
        pos = int(parts[2]) - 1  # 1-indexed in input

        if d == 'H':
            # Horizontal line of given length starting at column pos
            cols = list(range(pos, pos + length))
            y = 0
            while True:
                blocked = False
                if y > 0:
                    for c in cols:
                        if board[y - 1][c]:
                            blocked = True
                            break
                if blocked:
                    break
                y += 1
                ensure_height(y)
                # continue rising until the first blocked level;
                # actual resting row will be y-1
                if y > len(board):
                    ensure_height(y)

            rest = y - 1
            ensure_height(rest + 1)
            for c in cols:
                board[rest][c] = 1

        else:  # 'V'
            # Vertical line of given length in column pos
            c = pos
            base = 0
            while base < len(board) and board[base][c]:
                base += 1
            ensure_height(base + length)
            for y in range(base, base + length):
                board[y][c] = 1

        # Clear full rows
        new_board = []
        for row in board:
            if sum(row) < 5:
                new_board.append(row)
        board = new_board

    # Count remaining occupied cells (blocks)
    ans = sum(sum(row) for row in board)
    print(ans)

